							JCImport importDecl = (JCImport) unitDefinition;
							if (!importDecl.staticImport) {
								String importedType = Javac.getQualid(importDecl).toString();
								if (!importedType.isEmpty()) {
									if (importedType.equals(helperAnnotationName)) {
										JavacAugments.JCImport_deletable.set(importDecl, true);
									}
								}
							}
						}
					}
				} else if (annotationParentKind == Kind.METHOD) {
					JCMethodDecl annotatedMethod = (JCMethodDecl) annotationParent.get();
					ListBuffer<JCAnnotation> retainedMethodAnnotations = new ListBuffer<JCAnnotation>();
					for (JCAnnotation existingAnnotation : annotatedMethod.mods.annotations) {
						if (existingAnnotation != annotationTree) {
							retainedMethodAnnotations.append(existingAnnotation);
						}
