			JCStatement candidateStatement = statementIterator.next();
			if (candidateStatement == annotatedType_) {
				break;
			}
		}

		java.util.List<String> knownMethodNames = new ArrayList<String>();
		for (JavacNode child : annotatedType.down()) {
			if (child.getKind() != Kind.METHOD) {
				continue;
			}
			JCTree childTree = child.get();
			String methodName = child.getName();
			if (childTree instanceof JCMethodDecl) {
				JCMethodDecl methodDecl = (JCMethodDecl) childTree;
				if (methodDecl.name != null) {
					methodName = methodDecl.name.toString();
				}
				if (methodDecl.mods != null && (methodDecl.mods.flags & Flags.GENERATEDCONSTR) != 0) {
					continue;
				}
			}
			if (methodName != null && !methodName.isEmpty() && methodName.charAt(0) != '<') {
				knownMethodNames.add(methodName);
			}
		}

		Collections.sort(knownMethodNames);
		final String[] knownMethodNames_ = knownMethodNames.toArray(new String[0]);
		final Name helperName = annotationNode.toName("$" + annotatedType_.name);
		final boolean[] helperUsed = new boolean[1];
		final JavacTreeMaker maker = annotationNode.getTreeMaker();
		final java.util.List<JCMethodInvocation> invocations = new ArrayList<JCMethodInvocation>();
		TreeVisitor<Void, Void> invocationCollector = new TreeScanner<Void, Void>() {
			@Override public Void visitMethodInvocation(MethodInvocationTree node, Void p) {
				invocations.add((JCMethodInvocation) node);
				return super.visitMethodInvocation(node, p);
			}
		};
		while (statementIterator.hasNext()) {
			JCStatement remainingStatement = statementIterator.next();
			remainingStatement.accept(invocationCollector, null);
		}

		final java.util.List<JCTree> generatedPieces = new ArrayList<JCTree>();
		com.sun.tools.javac.tree.TreeScanner generatedPieceCollector = new com.sun.tools.javac.tree.TreeScanner() {
			@Override public void scan(JCTree tree) {
				if (tree == null) return;
				generatedPieces.add(tree);
				super.scan(tree);
			}
		};

		for (JCMethodInvocation invocation : invocations) {
			if (invocation.meth instanceof JCIdent) {
				JCIdent invokedIdent = (JCIdent) invocation.meth;
				if (invokedIdent.name != null && Arrays.binarySearch(knownMethodNames_, invokedIdent.name.toString()) >= 0) {
					JCExpression helperReceiver = maker.Ident(helperName);
					JCExpression rewrittenInvocation = maker.Select(helperReceiver, invokedIdent.name);
					invocation.meth = rewrittenInvocation;
